using System.Diagnostics;using System.IO;using System.Windows;using System.Windows.Controls;namespace DirectorFamilyTravelDesk.Views;public partial class BackupView:UserControl,IRefreshable{public BackupView(){InitializeComponent();}public void RefreshData(){PathText.Text=App.Repository.DatabasePath;}private string Docs(){var p=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"Director Family Travel Desk");Directory.CreateDirectory(p);return p;}private void Backup_Click(object s,RoutedEventArgs e){var dir=Path.Combine(Docs(),"Backups");Directory.CreateDirectory(dir);var p=Path.Combine(dir,$"travel_{DateTime.Now:yyyyMMdd_HHmmss}.db");App.Repository.Backup(p);ResultText.Text=$"Backup created: {p}";}private void Export_Click(object s,RoutedEventArgs e){var dir=Path.Combine(Docs(),"Exports");Directory.CreateDirectory(dir);var p=Path.Combine(dir,$"trips_{DateTime.Now:yyyyMMdd_HHmmss}.csv");App.Repository.ExportTripsCsv(p);ResultText.Text=$"Export created: {p}";}private void OpenFolder_Click(object s,RoutedEventArgs e)=>Process.Start(new ProcessStartInfo("explorer.exe",App.DataDirectory){UseShellExecute=true});private void OpenReference_Click(object s,RoutedEventArgs e){var p=Path.Combine(AppContext.BaseDirectory,"Reference","Director_Family_Travel_Smart_UI_v8_3_City_Flight_Coverage.xlsx");if(File.Exists(p))Process.Start(new ProcessStartInfo(p){UseShellExecute=true});else MessageBox.Show("Reference workbook was not found beside the application.");}}